 const title=cycle?`${base}（第${cycle+1}期）`:base;
 const cat=CATEGORIES[i%CATEGORIES.length];
 const r={id,module:key,title,subtitle:key==='news'?'深入一线调研　推动重点工作落实':'',source:key==='notice'?'':key==='honor'?'集团公司':'综合办公室',author:i%3===0?'张三':i%3===1?'李四':'王五',department:key==='honor'?'集团公司':'综合办公室',createdAt:created,publishedAt:ever?published:null,scheduledAt:key==='notice'?published:null,expiresAt:key==='notice'&&(i%7===0)?'2026-12-31 23:59':null,longTerm:key==='notice'&&i%7!==0,categoryId:key==='notice'?cat.id:null,categoryName:key==='notice'?cat.name:null,audienceMode:'all',audienceText:'全部有效员工',content:BODIES[key],cover:m.hasCover&&i%3!==2?'assets/images/project-scene.svg':'',attachments:[{id:`a-${id}`,name:key==='notice'?'安全培训日程.pdf':key==='showcase'?'项目建设情况说明.pdf':'相关工作材料.pdf',size:540672,type:'application/pdf',data:''}],pinned:m.hasPin&&i<2,publishStatus:publish,flowStatus:flow,everPublishedAt:ever,activeVersion:ever?1:0,reads:key==='notice'&&ever?Array.from({length:i%9},(_,x)=>({userId:`seed-${x}`,name:['赵强','钱敏','孙楠','周宇'][x%4],title:'项目工程师',department:'工程管理部',readAt:published})):[],versions:ever?[{version:1,title,subtitle:key==='news'?'深入一线调研　推动重点工作落实':'',source:key==='notice'?'':'综合办公室',author:'张三',department:'综合办公室',categoryName:key==='notice'?cat.name:null,content:BODIES[key],cover:m.hasCover&&i%3!==2?'assets/images/project-scene.svg':'',attachments:[{id:`a-${id}`,name:'相关工作材料.pdf',size:540672,type:'application/pdf',data:''}],publishedAt:published}]:[],modificationCount:m.hasCount?(ever?i%3:0):null,draft:null,workflow:flow==='pending'?{instanceId:`wf-${id}`,version:2,eventId:null,submittedAt:dt(0,'08:40'),type:'modify'}:null,revision:1,deletedAt:null,shareToken:m.share&&i===0?token():null};
 if(i===2)r.draft={...pickEditable(r),title:`${title}（修订稿）`};
