function pickEditable(r){return {title:r.title,subtitle:r.subtitle||'',source:r.source||'',content:r.content||'',cover:r.cover||'',attachments:deep(r.attachments||[]),categoryId:r.categoryId||'',categoryName:r.categoryName||'',scheduleMode:r.scheduledAt?'scheduled':'immediate',scheduledAt:r.scheduledAt||'',validityMode:r.longTerm?'long':'expires',expiresAt:r.expiresAt||'',audienceMode:r.audienceMode||'all',audienceText:r.audienceText||'全部有效员工'}}
