function icon(name,size=16){const p={home:'<path d="M3 10.5 12 3l9 7.5v9a1.5 1.5 0 0 1-1.5 1.5h-15A1.5 1.5 0 0 1 3 19.5z"/><path d="M9 21v-7h6v7"/>',list:'<path d="M8 6h13M8 12h13M8 18h13"/><circle cx="3.5" cy="6" r="1" fill="currentColor"/><circle cx="3.5" cy="12" r="1" fill="currentColor"/><circle cx="3.5" cy="18" r="1" fill="currentColor"/>',news:'<path d="M4 4h16v16H4z"/><path d="M8 8h4v4H8zM14 8h3M14 11h3M8 15h9M8 18h9"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M9.5 21h5"/>',award:'<circle cx="12" cy="9" r="6"/><path d="m8 14-1 7 5-3 5 3-1-7"/>',image:'<rect x="3" y="4" width="18" height="16" rx="1"/><path d="m4 17 5-5 4 4 3-3 5 4M8 9h.01"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',reset:'<path d="M4 7v5h5M5 12a8 8 0 1 0 2-6"/>',download:'<path d="M12 3v12m0 0 5-5m-5 5-5-5M4 21h16"/>',trash:'<path d="M4 7h16M9 3h6l1 4H8zM7 7l1 14h8l1-14"/>',pin:'<path d="m8 3 8 8m-6-6 7 2-4 4 2 7-3 3-4-7-5-5zM3 21l6-6"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',back:'<path d="m15 18-6-6 6-6"/>',link:'<path d="M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2"/>',upload:'<path d="M12 16V4m0 0L7 9m5-5 5 5M4 20h16"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',file:'<path d="M6 2h8l4 4v16H6zM14 2v5h5M9 12h6M9 16h6"/>',check:'<path d="m5 12 4 4L19 6"/>',warn:'<path d="M12 3 2 21h20zM12 9v5M12 18h.01"/>'}[name]||'<circle cx="12" cy="12" r="8"/>';return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p}</svg>`}
function btn(label,action,opt={}){return `<button type="button" class="btn ${opt.kind||''} ${opt.small?'small':''}" data-action="${action}" ${opt.disabled?'disabled':''} ${opt.id?`data-id="${esc(opt.id)}"`:''}>${opt.icon?icon(opt.icon):''}${label}</button>`}
function toast(msg,type='ok'){const id=Date.now()+Math.random();app.toasts.push({id,msg,type});renderToasts();setTimeout(()=>{app.toasts=app.toasts.filter(x=>x.id!==id);renderToasts()},3300)}
function renderToasts(){let box=document.querySelector('.toast-stack');if(!box){box=document.createElement('div');box.className='toast-stack';document.body.appendChild(box)}box.innerHTML=app.toasts.map(t=>`<div class="toast ${t.type}">${esc(t.msg)}</div>`).join('')}
