function color(s){return ['approved','published'].includes(s)?'green':['pending','paused','scheduled'].includes(s)?'orange':['rejected'].includes(s)?'red':'gray'}
function perms(key){const role=app.user.role;if(role==='admin')return {view:true,create:true,edit:true,delete:true,export:true,history:true,pin:MODS[key].hasPin,down:MODS[key].hasDown,share:MODS[key].share,read:MODS[key].read,categories:key==='notice'};if(role==='editor')return {view:true,create:true,edit:true,delete:true,export:['news','showcase'].includes(key),history:['news','showcase'].includes(key),pin:['news','honor'].includes(key),down:['news','notice'].includes(key),share:key==='honor',read:key==='notice',categories:false};return {view:false,create:false,edit:false,delete:false,export:false,history:false,pin:false,down:false,share:false,read:false,categories:false}}
