function currentRecord(k,id){return (app.db.modules[k]||[]).find(x=>x.id===id&&!x.deletedAt)}
function nowMs(){return Math.max(Date.now(),new Date(TODAY).getTime())}
function effectivePub(r){if(!r)return 'unpublished';if(['down','paused','unpublished'].includes(r.publishStatus))return r.publishStatus;if(r.module==='notice'&&r.expiresAt&&new Date(r.expiresAt.replace(' ','T')+'+08:00').getTime()<=nowMs())return 'expired';if(r.module==='notice'&&r.scheduledAt&&new Date(r.scheduledAt.replace(' ','T')+'+08:00').getTime()>nowMs())return 'scheduled';return r.everPublishedAt&&r.flowStatus==='approved'?'published':r.publishStatus}
function visible(r,external=false){return !!(r&&!r.deletedAt&&r.flowStatus==='approved'&&r.everPublishedAt&&effectivePub(r)==='published')}
function sortRecords(key,rows){return rows.slice().sort((a,b)=>{if(MODS[key].hasPin&&a.pinned!==b.pinned)return a.pinned?-1:1;const ad=a.pinned?a.createdAt:(a.publishedAt||a.createdAt),bd=b.pinned?b.createdAt:(b.publishedAt||b.createdAt);return bd.localeCompare(ad)||b.id.localeCompare(a.id)})}
