function topbar(){const portal=app.route.area==='portal'||app.route.area==='share';return `<header class="topbar"><div class="brand"><img src="assets/images/workbench-mark.svg" alt=""><span>企业级工作台</span></div><nav class="topnav"><button data-action="portal-home" class="${portal?'active':''}">门户</button><button>市场经营</button><button>工程管理</button><button>人力资源</button><button>财务管理</button><button data-action="admin-home" class="${!portal?'active':''}">行政综合</button><button>常用网址</button><button>AI知识库</button><button>大屏数据</button><button class="topnav-add" aria-label="添加工作台">＋</button></nav><div class="top-actions"><span class="screen-entry">数字大屏</span><span class="top-action">提醒<i>9+</i></span><span class="top-action">待办<i>36</i></span><span class="top-dot">${esc(app.user.name.slice(0,1))}</span><label><span class="hidden">演示账号</span><select class="role-select" data-action="role-change"><option value="admin" ${app.user.role==='admin'?'selected':''}>管理员</option><option value="editor" ${app.user.role==='editor'?'selected':''}>内容编辑</option><option value="employee" ${app.user.role==='employee'?'selected':''}>普通员工</option></select></label><button class="reset-demo" data-action="reset-demo">重置</button></div></header>`}
